// Recebe { url: "https://x.com/usuario/status/123..." } no corpo da requisicao.
// Aceita qualquer tweet da thread (o primeiro, o ultimo ou um do meio):
// a busca segue a cadeia in_reply_to_status_id_str para tras ate a raiz,
// contanto que cada resposta seja do MESMO autor (auto-resposta encadeada).
// Usa o endpoint publico de sindicacao do Twitter/X (o mesmo usado para
// embeds de tweets em sites de terceiros) - nao requer API key nem login.

const SYNDICATION_URL = 'https://cdn.syndication.twimg.com/tweet-result';
const MAX_HOPS = 200;

function extrairId(urlOuId) {
  if (/^\d+$/.test(urlOuId)) return urlOuId;
  const m = urlOuId.match(/(?:twitter\.com|x\.com)\/[^/]+\/status\/(\d+)/);
  if (!m) throw new Error(`Não foi possível extrair o ID do tweet de: ${urlOuId}`);
  return m[1];
}

function token(id) {
  // Mesma fórmula pública usada por bibliotecas de embed (ex.: react-tweet).
  return ((Number(id) / 1e15) * Math.PI).toString(36).replace(/(0+|\.)/g, '');
}

async function buscarTweet(id) {
  const resp = await this.helpers.httpRequest({
    url: `${SYNDICATION_URL}?id=${id}&token=${token(id)}`,
    method: 'GET',
    json: true,
  });
  const u = resp.user || {};
  return {
    id: resp.id_str,
    autor_nome: u.name || '',
    autor_usuario: u.screen_name || '',
    texto: resp.text || '',
    criado_em: resp.created_at || '',
    curtidas: resp.favorite_count || 0,
    respostas: resp.conversation_count || 0,
    retweets: resp.retweet_count || 0,
    in_reply_to_id: resp.in_reply_to_status_id_str || null,
    in_reply_to_usuario: resp.in_reply_to_screen_name || null,
  };
}

const entrada = $input.first().json;
const urlEntrada = entrada.url || (entrada.body && entrada.body.url);
if (!urlEntrada) {
  throw new Error('Informe "url" no corpo da requisição (JSON: { "url": "https://x.com/usuario/status/123" }).');
}

const idInicial = extrairId(urlEntrada);
let atual = await buscarTweet.call(this, idInicial);
const autor = atual.autor_usuario;
const cadeia = [atual];

let hops = 0;
while (atual.in_reply_to_id && atual.in_reply_to_usuario === autor && hops < MAX_HOPS) {
  atual = await buscarTweet.call(this, atual.in_reply_to_id);
  cadeia.push(atual);
  hops++;
}

cadeia.reverse(); // raiz primeiro, tweet informado por último
const classificacao = cadeia.length > 1 ? 'thread' : 'tweet_unico';

return [{
  json: {
    classificacao,
    total_tweets: cadeia.length,
    autor_usuario: cadeia[0].autor_usuario,
    autor_nome: cadeia[0].autor_nome,
    tweets: cadeia,
  },
}];

// Monta um texto limpo e legível (Markdown) a partir dos tweets já ordenados.
const dado = $input.first().json;
const { classificacao, tweets } = dado;

const linhas = [];
linhas.push(
  classificacao === 'thread'
    ? `# Thread de @${tweets[0].autor_usuario} (${tweets[0].autor_nome})`
    : `# Tweet de @${tweets[0].autor_usuario} (${tweets[0].autor_nome})`
);
linhas.push('');
linhas.push(`- Classificação: **${classificacao}**`);
linhas.push(`- Total de tweets: **${tweets.length}**`);
linhas.push(`- Primeiro tweet: ${tweets[0].criado_em}`);
linhas.push('');
linhas.push('---');
linhas.push('');

tweets.forEach((t, i) => {
  const prefixo = classificacao === 'thread' ? `**${i + 1}/${tweets.length}** ` : '';
  linhas.push(`${prefixo}${t.texto}`);
  linhas.push(`\n*${t.curtidas} curtidas - ${t.respostas} respostas - ${t.retweets} retweets*`);
  linhas.push('');
});

return [{
  json: {
    ...dado,
    texto_formatado: linhas.join('\n'),
  },
}];

